 std::printf("\tPadding:\t%05.2f %.2f %5.2f\n", 1.5, 1.5, 1.5);
 std::printf("\tScientific:\t%E %e\n", 1.5, 1.5);
 std::printf("\tHexadecimal:\t%a %A\n", 1.5, 1.5);
